import win32api
import win32con

 def get_key_state ( key ) :
 try :
 key_state = win32api . GetKeyState ( key ) [ 0 ]
 except IndexError :
 key_state = 0
 return key_state & win32con . KEYSTATE_MASK
 def get_key_name ( key ) :
 try :
 key_name = win32api . MapVirtualKey ( key , win32con . MAP_VK_TO_CHAR )
 except IndexError :
 key_name = '<unnamed>'
 return key_name
 def main ( ) :
 while True :
 key_state = win32api . GetAsyncKeyState ( win32con . VK_ESCAPE ) [ 0 ]
 if key_state & win32con . KEYSTATE_MASK :
 break
 print 'You pressed the Escape key.'
 key_state = win32api . GetAsyncKeyState ( '<unnamed>' ) [ 0 ]
 if key_state & win32con . KEYSTATE_MASK :
 break
 print 'You pressed a key.'
 key = win32api . GetMessageW ( )
 if key == win32con . WM_QUIT :
 break
 win32api . TranslateMessage ( key )
 win32api . DispatchMessageW ( )
